val Context.settingsStore by preferencesDataStore(name = "settings")

private val DARK_MODE = booleanPreferencesKey("dark_mode")

fun darkModeFlow(context: Context): Flow<Boolean> =
    context.settingsStore.data.map { prefs -> prefs[DARK_MODE] ?: false }

suspend fun setDarkMode(context: Context, enabled: Boolean) {
    context.settingsStore.edit { prefs -> prefs[DARK_MODE] = enabled }
}

// Wrong: every call creates another DataStore for the same file
fun settings(context: Context) =
    PreferenceDataStoreFactory.create { context.preferencesDataStoreFile("settings") }

// Right: one top-level delegate (or one DI singleton)
val Context.settingsStore by preferencesDataStore(name = "settings")

val Context.settingsStore by preferencesDataStore(
    name = "settings",
    produceMigrations = { context ->
        listOf(SharedPreferencesMigration(context, "legacy_prefs"))
    }
)

val settings: Flow<Preferences> = context.settingsStore.data
    .catch { e ->
        if (e is IOException) emit(emptyPreferences()) else throw e
    }

suspend fun saveSession(token: String, userId: String) {
    context.settingsStore.edit { prefs ->
        prefs[TOKEN] = token    // both keys change together
        prefs[USER_ID] = userId
    }
}

@Serializable
data class UserSettings(val theme: String = "system", val notifications: Boolean = true)

object UserSettingsSerializer : Serializer<UserSettings> {
    override val defaultValue = UserSettings()

    override suspend fun readFrom(input: InputStream): UserSettings = try {
        Json.decodeFromString(UserSettings.serializer(), input.readBytes().decodeToString())
    } catch (e: SerializationException) {
        throw CorruptionException("Cannot read settings", e)
    }

    override suspend fun writeTo(t: UserSettings, output: OutputStream) {
        output.write(Json.encodeToString(UserSettings.serializer(), t).encodeToByteArray())
    }
}

val Context.userSettings by dataStore("user_settings.json", UserSettingsSerializer)

suspend fun setTheme(context: Context, theme: String) =
    context.userSettings.updateData { it.copy(theme = theme) }

